[
  {
    "id": "90000000-0000-0000-0000-000000000356",
    "title": "Life of David W. Patten, the First Apostolic Martyr",
    "description": "The public-domain text of Life of David W. Patten, the First Apostolic Martyr by Lycurgus A. Wilson, preserved across 8 original sections with extracted Scripture references.",
    "total_days": 18,
    "tags": [
      "knowledge",
